# Cards: organs, air sacs and lungs, nerves, and the cut-open details (syrinx, eye, heart).
from robin_lib import *
CROP = src('Crop (anatomy) (Wikipedia)', 'https://en.wikipedia.org/wiki/Crop_(anatomy)')
def S(id, title, scale, summary, basics, deeper, expert, facts, **kw): return N(id, title, 'structure', scale, kw.pop('parents', ['robin']), summary, basics, deeper, expert, facts, **kw)

S('robin_heart', 'Heart', .012, 'A four-chambered heart, large and fast for the bird\'s size, that pumps blood to the flight muscles.',
  'The heart has four chambers: two atria that receive blood and two ventricles that pump it. The right side sends blood to the lungs; the left side sends it round the body. The two sides do not mix, so the muscles get blood full of oxygen. A bird\'s heart has to supply the most energy-hungry muscles of any animal, so it is large and beats very fast. Use "Cut open: the heart" to see the chambers.',
  'Oxygen-poor blood comes into the right atrium, passes to the right ventricle, goes to the lungs, returns to the left atrium and is pumped by the left ventricle round the body. The wall of the left ventricle is the thickest. The model\'s heart pulses as an illustration, with no real rate.',
  'A small songbird\'s heart beats several hundred times a minute: a similar-sized tropical songbird in the wild ranged from 260 to 824 beats a minute, mean 492 (Steiger et al. 2009). Relative heart size is a good indicator of how much a bird or mammal can sustain locomotion for a long time. ',
  [['Chambers', '4 (WBA)'], ['Heart rate, spotted antbird (≈ 17 g)', '260 to 824 beats/min, mean 492']], cert='C1', refs=[R_CIRC], ext=[WBA, STE], related=['heart', 'robin_temperature'], parts=['robin_lv', 'robin_rv', 'robin_la', 'robin_ra'])
S('robin_lv', 'Left ventricle', .004, 'The thick-walled chamber that pumps oxygen-rich blood round the whole body.', 'The left ventricle receives blood that has been to the lungs and pumps it to the body through the main artery (the aorta). Its wall is the thickest in the heart.', 'The main artery (the aorta) leaves the heart and curves to the body.', 'The cavity is drawn as an ellipsoid inside the heart muscle.', [['Blood', 'oxygen-rich']], refs=[R_CIRC], ext=[WBA], related=['heart'], parents=['robin_heart'])
S('robin_rv', 'Right ventricle', .004, 'The chamber that pumps oxygen-poor blood to the lungs.', 'The right ventricle wraps round part of the left one. It sends blood to the lungs for oxygen.', 'Its wall is thinner than that of the left ventricle.', 'A crescent in the model.', [['Blood', 'oxygen-poor']], refs=[R_CIRC], ext=[WBA], related=['heart'], parents=['robin_heart'])
S('robin_la', 'Left atrium', .002, 'The small chamber that receives oxygen-rich blood from the lungs.', 'Blood returns from the lungs to the left atrium and flows on to the left ventricle.', 'The atria are thin-walled receiving chambers.', 'Drawn as a small ellipsoid.', [['Blood', 'oxygen-rich']], refs=[R_CIRC], ext=[WBA], related=['heart'], parents=['robin_heart'])
S('robin_ra', 'Right atrium', .002, 'The small chamber that receives oxygen-poor blood from the body.', 'Blood from the body returns to the right atrium and flows on to the right ventricle.', 'The atria are thin-walled receiving chambers.', 'Drawn as a small ellipsoid.', [['Blood', 'oxygen-poor']], refs=[R_CIRC], ext=[WBA], related=['heart'], parents=['robin_heart'])
S('robin_liver', 'Liver', .012, 'The liver, a large two-lobed organ behind the heart.', 'The liver is the biggest gland of the body. It makes bile, which helps digest fat, stores sugar and cleans the blood. In a bird it has two lobes, the right slightly bigger.', 'It lies just behind the heart, in front of the stomach.', 'Drawn as two lobes.', [['Lobes', '2']], refs=[R_DIG], ext=[WBA], related=['liver'])
S('robin_oesophagus', 'Gullet (oesophagus), and the crop question', .06, 'The tube from the throat to the stomach. Some birds have a crop, a pouch for storing food; the model draws none.',
  'Food goes from the throat to the stomach down the gullet, behind the windpipe. Many birds have a crop on the way down, an enlarged part of the gullet where food is stored and softened; not all birds have one (owls do not). The model draws the robin\'s gullet as a tube with only a gentle widening low in the neck, and no crop.',
  'A crop is "essentially an enlarged part of the oesophagus". Descriptions of songbirds often mention a slight widening of the lower gullet rather than a true crop.',
  'Descriptions of songbird anatomy differ on whether a true crop is present; the model draws a small widening only.',
  [['Crop', 'absent in some birds (owls); robin drawn without a true crop']], cert='C2', refs=[R_DIG], ext=[CROP, WBA], openq=['Does the robin have a true crop or only a small widening of the lower gullet?'], related=['esophagus'])
S('robin_proventriculus', 'Proventriculus: the glandular stomach', .006, 'The first of the bird\'s two stomachs: it adds acid and enzymes.', 'A bird\'s stomach has two parts. The first, the proventriculus, makes digestive juices. The food then goes to the muscular second part, the gizzard.', 'Acid, mucus and the enzyme pepsin are made here.', 'Drawn as a small oval.', [['Stomach parts', '2: glandular and muscular']], refs=[R_DIG], ext=[WBA], related=['stomach'])
S('robin_gizzard', 'Gizzard: the muscular stomach', .01, 'The gizzard is the muscle that grinds food, doing the work of teeth.', 'Birds have no teeth; they grind food in the gizzard, a thick-walled muscular stomach. Some birds swallow grit to help.', 'The gizzard is made of four muscular bands. Gizzard stones are shared with the dinosaurs birds came from.', 'Drawn as a rounded disc.', [['Muscle bands', '4 (WBA)']], refs=[R_DIG], ext=[WBA, ORI, WR], related=['stomach'])
S('robin_spleen', 'Spleen', .003, 'A small dark organ beside the stomach that handles blood and immune cells.', 'The spleen is a small round organ near the stomach. It filters the blood and stores immune cells.', 'It is part of the immune system.', 'Drawn as a small ball.', [['Where', 'next to the stomach']], refs=[R_HOM], ext=[WBA], related=['spleen'])
S('robin_pancreas', 'Pancreas', .008, 'A thin gland that lies in the loop of the first part of the gut and makes digestive enzymes and hormones.', 'The pancreas makes enzymes that go into the gut and hormones such as insulin and glucagon. It lies in the loop of the gut.', 'Compared with mammals birds have a lower insulin-to-glucagon ratio, and fasting blood sugar is 150 to 300 % higher.', 'Drawn as a thin rod.', [['Hormones', 'glucagon, insulin (WBA)']], refs=[R_DIG], ext=[WBA], related=['pancreas'])
S('robin_intestines', 'Intestines and rectum', .02, 'The gut tube coils in the belly and ends in a short rectum and the cloaca.', 'Food passes from the gizzard along the small intestine, where it is digested and absorbed, to a short rectum. A bird\'s gut is short, which keeps its weight down.', 'The first part makes a loop around the pancreas.', 'Drawn as a coiled tube; the real gut is more folded.', [['Ends in', 'cloaca']], refs=[R_DIG], ext=[WBA], related=['small_intestine', 'large_intestine'], parts=['robin_rectum'])
S('robin_rectum', 'Rectum', .004, 'The last short piece of the gut.', 'See the Intestines card.', 'It opens into the cloaca.', 'Drawn as a short tube.', [['Opens into', 'cloaca']], refs=[R_DIG], ext=[WBA], parents=['robin_intestines'], related=['large_intestine'])
S('robin_cloaca', 'Cloaca: one opening for everything', .005, 'Gut, kidneys and reproductive organs all open into one chamber, the cloaca.', 'A bird has one exit for droppings, urine and eggs or sperm. A bird\'s waste nitrogen leaves as uric acid, a white paste, together with the faeces.', 'The bursa of Fabricius, an organ that makes some immune cells in young birds, is a pouch attached to the top of the cloaca.', 'Drawn as a small chamber.', [['Openings', 'gut, kidneys, reproductive tract']], refs=[R_EXC], ext=[WBA], related=['robin_vent'])
S('robin_kidneys', 'Kidneys', .015, 'Two kidneys, in hollows under the fused lower back, that clean the blood and make uric acid.', 'The kidneys filter waste from the blood. In a bird each kidney has three lobes and lies in a hollow of the pelvis. Birds make uric acid, which needs little water.', 'There is no bladder; urine goes to the cloaca.', 'Drawn as three lobes on each side.', [['Lobes', '3 each side']], refs=[R_EXC], ext=[WBA], related=['kidney_r'])
S('robin_eyeballs', 'Eyeballs', .008, 'The two eyeballs, each about 8 mm across in the model, set in sockets at the sides of the skull.', 'The eyeballs fill a large part of the head. Each eye has a cornea, a lens and a retina; a bird\'s retina has a pleated fold, the pecten. Use "Cut open: the eye" to look inside one.', 'A ring of small bones in the front of the eye supports its shape.', 'The size is drawn by eye from the proportions of a robin\'s head; it is not measured.', [['Eyeball (model)', '≈ 8 mm']], refs=[R_VIS], ext=[SCL, PECT], related=['robin_eye', 'robin_retina'])

# ------------------------------------------------ air sacs and lungs
S('robin_lungs', 'Lungs', .02, 'The lungs are small, spongy and fixed against the ribs; they do not expand, the air sacs move the air.', 'A bird\'s lungs are small and firm, pressed against the back of the rib cage. They do not swell and shrink: the air sacs do the pumping. Gas exchange takes place in tiny tubes, the parabronchi, with a one-way flow of air.', 'See the card on how a robin breathes.', 'The lung is drawn as a wedge on each side of the spine.', [['Lungs', '2'], ['Airflow', 'one way through the lung']], refs=[R_GAS, R_ARESP], ext=[AIR, WBA], related=['lung_r', 'robin_breathing'])
S('robin_air_sacs', 'Air sacs', .015, 'Thin-walled air sacs fill much of the body and work as bellows, so that air flows through the lung in one direction.', 'Air sacs are thin bags that sit among the organs and even in some bones. They hold air and act as bellows. Fresh air goes first into the rear sacs, then through the lungs, then to the front sacs and out. Nine are usual in birds; the model draws one in the front of the chest (interclavicular), a pair in the neck base (cervical), two pairs in the chest (anterior and posterior thoracic) and a pair in the belly (abdominal).', 'The posterior sacs receive most of the inhaled air; the anterior sacs empty through the windpipe.', 'Wikipedia says passerines have seven sacs; descriptions differ, and the model draws the usual nine.', [['Air sacs', 'typically nine (range 7 to 12)']], cert='C2', refs=[R_GAS], ext=[AIR, WBA], openq=['How many air sacs a robin has: descriptions differ (nine in the textbook pattern, seven for passerines in one source).'], related=['robin_breathing'], parts=['robin_sac_interclav', 'robin_sac_cervical', 'robin_sac_ant', 'robin_sac_post', 'robin_sac_abd'])
for _id, _t, _s in [('robin_sac_interclav', 'Interclavicular air sac', 'The single air sac in the front of the chest, around the syrinx.'), ('robin_sac_cervical', 'Cervical air sacs', 'A pair of small air sacs at the base of the neck.'), ('robin_sac_ant', 'Anterior thoracic air sacs', 'A pair of air sacs in the front of the chest.'), ('robin_sac_post', 'Posterior thoracic air sacs', 'A pair of air sacs in the rear of the chest.'), ('robin_sac_abd', 'Abdominal air sacs', 'A pair of large air sacs among the gut.')]:
    S(_id, _t, .01, _s, 'This is one of the bird\'s air sacs. The front group (interclavicular, anterior thoracic, cervical) empty through the windpipe; the rear group (posterior thoracic and abdominal) receive most inhaled air. See the Air sacs card.', 'The sacs work as bellows.', 'Drawn as a smooth bag.', [['Group', 'anterior' if _id in ('robin_sac_interclav', 'robin_sac_cervical', 'robin_sac_ant') else 'posterior']], refs=[R_GAS], ext=[AIR], parents=['robin_air_sacs'], related=['robin_breathing'])
S('robin_trachea', 'Windpipe (trachea)', .045, 'The windpipe is a tube of rings from the throat to the syrinx, deep in the chest.', 'The trachea carries air from the throat to the lungs, down the front of the neck. It is held open by rings of cartilage. At its lower end it splits in two at the syrinx, where the sound is made.', 'The tracheal rings are mostly complete rings; the bronchi have C-shaped rings.', 'Drawn as a smooth tube; the cut-open syrinx view shows the rings.', [['Rings', 'mostly complete (SYR)']], refs=[R_ARESP], ext=[SYR, WBA], related=['trachea', 'robin_syrinx'])

# ------------------------------------------------ nerves
S('robin_brain', 'Brain', .015, 'The brain: a smooth, small brain with large optic lobes.', 'Much of the brain deals with sight: the optic lobes at the sides are large, because vision matters so much to a bird. The cerebellum at the back controls balance and movement.', 'A bird\'s brain is smooth, without the folds of a human brain.', 'Drawn by eye from a typical songbird brain.', [['Parts drawn', 'cerebrum, cerebellum, optic lobes']], refs=[R_CNS], ext=[WBA], related=['brain', 'bio_brain_organization'])
S('robin_optic_lobes', 'Optic lobes', .006, 'The parts of the brain that receive signals from the eyes.', 'The optic lobes are two bulges at the sides of the midbrain. They receive the signals from the optic nerves.', 'They are large in birds.', 'Drawn as ellipsoids.', [['Receives', 'optic nerves']], refs=[R_CNS, R_VIS], ext=[WBA], related=['optic_nerve'])
S('robin_optic_nerves', 'Optic nerves', .008, 'The cables that carry signals from each eye to the brain.', 'Each optic nerve leaves the back of the eye and runs to the brain.', 'The nerve leaves the retina where the pecten stands.', 'Drawn as thin cables.', [['Number', '2']], refs=[R_VIS], ext=[WBA], related=['optic_nerve'])
S('robin_spinal_cord', 'Spinal cord', .1, 'The spinal cord runs from the brain through the vertebrae to the tail.', 'The spinal cord carries signals between the brain and the body. It runs in a canal inside the vertebrae.', 'Nerves leave it between the vertebrae to the wings, the legs and the muscles.', 'Drawn as a tube.', [['Where', 'inside the vertebral column']], refs=[R_CNS], ext=[WBA], related=['spinal_cord'])
S('robin_peripheral_nerves', 'Nerves of the wing and the leg, and the vagus', .05, 'Nerves branch from the spinal cord to the wings and legs; the vagus nerves run between the brain and the heart and gut.', 'The nerves of the wing come from a bundle (the brachial plexus) near the shoulder. The big nerve of the leg is the sciatic nerve. The vagus nerves run along the neck to the heart, lungs and gut.', 'These nerves have the same names as those in a human.', 'Drawn as thin cables.', [['Plexus', 'brachial, to the wing'], ['Leg', 'sciatic']], refs=[R_CNS], ext=[WBA], related=['spinal_cord'], parts=['robin_brachial', 'robin_sciatic', 'robin_vagus'])
for _id, _t in [('robin_brachial', 'Wing nerves (brachial plexus)'), ('robin_sciatic', 'Leg nerve (sciatic)'), ('robin_vagus', 'Vagus nerves')]:
    S(_id, _t, .03, 'See the card on the nerves of the wing and the leg.', 'The nerves of the wing and the leg branch from the spinal cord; the vagus nerves run along the neck.', 'Same names as in a human.', 'Drawn as thin cables.', [['Part of', 'peripheral nerves']], refs=[R_CNS], ext=[WBA], parents=['robin_peripheral_nerves'], related=['spinal_cord'])

# ------------------------------------------------ cut-open syrinx
S('robin_syrinx', 'Syrinx: where the song is made', .006, 'The syrinx is the bird\'s voice box, at the base of the windpipe where it forks, not in the throat.',
  'A bird\'s throat (the larynx) does not make its song. The sound is made lower down, deep in the chest, in the syrinx. It sits where the windpipe splits to go to the two lungs. Thin membranes vibrate as air passes, and muscles change their tension. The bird can control each side separately.',
  'In songbirds the syrinx is the tracheobronchial form: the lower trachea and the upper bronchi. The tracheal rings are mostly complete; the bronchial rings are C-shaped, with smooth muscle in the open part. Sound comes from vibration of the membrana tympaniformis and the pessulus.',
  'The syrinx is drawn at true size, a few millimetres wide, and simplified. The model windpipe is about 2 mm across; real dimensions vary between birds.',
  [['Position', 'where the windpipe forks, above the lungs'], ['Form', 'tracheobronchial in songbirds (SYR)']], refs=[R_ARESP, R_HEAR], ext=[SYR, WBA], related=['larynx', 'robin_song'], parts=['robin_pessulus', 'robin_tympaniform', 'robin_syr_muscles', 'robin_syr_rings', 'robin_bronchus'])
S('robin_pessulus', 'Pessulus', .0015, 'A small bony wedge at the fork of the windpipe, between the two bronchi.', 'The pessulus stands in the middle of the fork like the point of a Y. In songbirds it is bony. Air flows on both sides of it.', 'Sound comes from the vibration of the thin membranes and of the pessulus.', 'Drawn as a small wedge.', [['Material', 'bony in passerines (SYR)']], refs=[R_ARESP], ext=[SYR], parents=['robin_syrinx'])
S('robin_tympaniform', 'Tympaniform membranes', .001, 'Thin membranes in the wall of each bronchus that vibrate to make the sound.', 'When air from the lungs flows over them, the membranes vibrate, like the reed of a clarinet or the lips of a trumpeter. Each side has its own.', 'In most passerines the membrane that forms part of the first three bronchial rings makes the sound.', 'Drawn as small discs.', [['Position', 'medial wall of each bronchus']], refs=[R_ARESP], ext=[SYR], parents=['robin_syrinx'])
S('robin_syr_muscles', 'Syringeal muscles', .002, 'Small muscles that tune the syrinx; songbirds control them more finely than any other birds.', 'Muscles on the outside of each bronchus tighten the membranes and change the pitch. Songbirds have the finest control of these muscles of any bird, which allows their wide range of songs.', 'The intrinsic muscles are in the syrinx; the extrinsic muscles, such as the sternotrachealis, run from outside.', 'Drawn as a band on each bronchus.', [['Control', 'best among birds in songbirds (WPA)']], refs=[R_ARESP], ext=[SYR, WPA], parents=['robin_syrinx'])
S('robin_syr_rings', 'Rings of the windpipe and bronchi', .001, 'The rings of cartilage that hold the windpipe open; the bronchi have C-shaped rings.', 'The trachea is stiffened by rings of cartilage, mostly complete. The bronchi have C-shaped rings with smooth muscle along the open part.', 'The spacing changes near the syrinx.', 'Drawn as 9 rings and 8 C-shaped rings on each bronchus.', [['Tracheal rings', 'mostly complete'], ['Bronchial rings', 'C-shaped']], refs=[R_ARESP], ext=[SYR], parents=['robin_syrinx'])
S('robin_bronchus', 'Bronchus', .003, 'One of the two tubes that carry air from the syrinx to the lungs.', 'The bronchi carry air from the fork of the windpipe to each lung.', 'The syrinx covers the lowest part of the trachea and the upper bronchi.', 'Drawn leaving the fork at 40 degrees.', [['Number', '2']], refs=[R_ARESP], ext=[SYR], parents=['robin_syrinx'])

# ------------------------------------------------ cut-open eye
def EYE(id, title, summary, basics, deeper, expert, facts, **kw): S(id, title, .004, summary, basics, deeper, expert, facts, parents=['robin_eyeballs'], **kw)
EYE('robin_eye_sclera', 'Sclera', 'The tough white outer wall of the eyeball.', 'The sclera is the strong outer coat of the eye, white in humans, and keeps its shape.', 'In birds it carries a ring of small bones round the front.', 'Drawn as a shell.', [['Material', 'fibrous']], refs=[R_VIS], ext=[SCL], related=['robin_scleral_ring'])
EYE('robin_scleral_ring', 'Scleral ring: small bones in the eye', 'A ring of small bone plates in the front of the sclera, round the cornea.', 'In the front of a bird\'s eye there is a ring of thin bony plates (scleral ossicles) set in the sclera. They support the shape of the eye and give the muscles of focusing something to attach to.', 'Most birds have about 12 to 18 plates in each ring; 14 is most common.', 'Drawn as a single ring.', [['Plates', '12 to 18, most often 14 (Wikipedia)']], refs=[R_VIS], ext=[SCL])
EYE('robin_cornea', 'Cornea', 'The clear front window of the eye that does most of the focusing.', 'The cornea is the transparent front of the eye. It bends the light entering the eye.', 'In life the cornea is much thinner than drawn.', 'The shell is exaggerated for visibility.', [['Job', 'bends light']], refs=[R_VIS], ext=[SCL], related=['cornea'])
EYE('robin_iris', 'Iris and pupil', 'The coloured ring that sets the size of the pupil.', 'The iris is a ring of muscle round the pupil, the opening for light. A robin\'s eye looks black.', 'The iris adjusts the amount of light.', 'Drawn as a flat ring.', [['Colour', 'dark']], refs=[R_VIS], ext=[WR], related=['iris'])
EYE('robin_lens', 'Lens', 'The lens focuses light on the retina.', 'The lens sits behind the pupil. Muscles round it change its shape to focus on near and far.', 'In birds the muscles that change the shape of the lens attach to the ring of small bones.', 'Drawn as an ellipsoid.', [['Job', 'focus']], refs=[R_VIS], ext=[SCL], related=['lens'])
EYE('robin_vitreous', 'Vitreous body', 'The clear jelly that fills the eyeball behind the lens.', 'The vitreous fills most of the eye and holds the retina in place. Light passes through it.', 'The pecten reaches into it.', 'Drawn as a translucent sphere.', [['Filling', 'clear jelly']], refs=[R_VIS], ext=[PECT])
EYE('robin_choroid', 'Choroid', 'A dark, blood-rich layer behind the retina.', 'The choroid lies between the retina and the sclera. It is dark, which stops light bouncing around inside the eye, and it holds the blood vessels that feed the outer retina.', 'Birds\' retinas have almost no blood vessels of their own, so they rely on the choroid and the pecten.', 'Drawn as a thin dark shell.', [['Feeds', 'the outer retina']], refs=[R_VIS], ext=[PECT])
EYE('robin_retina', 'Retina', 'The light-sensitive layer at the back of the eye; click to look inside it.', 'The retina is the screen at the back of the eye. It is made of cells that respond to light and pass signals along the optic nerve. Use the button to look inside it.', 'A bird\'s retina is largely free of blood vessels.', 'See the retina scene for the cells.', [['Vessels', 'largely absent; fed by the choroid and the pecten (Wikipedia)']], refs=[R_VIS], ext=[PECT], related=['retina'], parts=['robin_retina_scene'])
EYE('robin_pecten', 'Pecten: the pleated fold in the eye', 'The pecten is a pleated, blood-rich fold that stands out from the retina into the jelly, found only in birds.', 'In birds the retina has few blood vessels of its own. A fold of tissue, the pecten (Latin for "comb of the eye"), projects from where the optic nerve enters the eye into the vitreous. It brings blood to feed the retina.', 'The pecten has blood vessels, dark pigment cells and supporting tissue, and no muscle or nerve fibres. The pleated type is the commonest and has 5 to 30 pleats. The leading idea is that it nourishes the retina and keeps the vitreous healthy; when the eye makes quick movements the pecten oscillates and stirs the jelly.', 'The model draws seven pleats.', [['Pleats', '5 to 30 in the pleated type (Wikipedia)'], ['Found in', 'birds only']], cert='C2', refs=[R_VIS], ext=[PECT], openq=['What is the main job of the pecten: feeding the retina, controlling the vitreous pH, absorbing stray light, or all of them?'])
EYE('robin_optic_nerve', 'Optic nerve', 'The cable of nerve fibres from the retina to the brain.', 'The optic nerve leaves the back of the eye where the pecten stands and runs to the brain.', 'It carries the signals of all the retina\'s ganglion cells.', 'Drawn as a cable.', [['Job', 'carries signals to the brain']], refs=[R_VIS], ext=[PECT], related=['optic_nerve'])
